import{_ as c,C as r,o as h,c as n,j as e,a as i,E as t,b as l,w as o,a6 as d,a5 as A}from"./chunks/framework.D_J2JZBr.js";const x=JSON.parse('{"title":"科研方向巡礼","description":"从器件、电路、系统与设计方法学认识上科大集成电路研究方向。","frontmatter":{"title":"科研方向巡礼","description":"从器件、电路、系统与设计方法学认识上科大集成电路研究方向。"},"headers":[],"relativePath":"explore-ic/research-directions/index.md","filePath":"explore-ic/research-directions/index.md","lastUpdated":1795531638000}'),B={name:"explore-ic/research-directions/index.md"};function p(u,a,b,f,g,m){const E=r("TopologyGraph"),s=r("Mermaid");return h(),n("div",null,[a[1]||(a[1]=e("h1",{id:"科研方向巡礼",tabindex:"-1"},[i("科研方向巡礼 "),e("a",{class:"header-anchor",href:"#科研方向巡礼","aria-label":'Permalink to "科研方向巡礼"'},"​")],-1)),t(E),a[2]||(a[2]=e("p",null,"悬停可高亮关联关系，点击方向进入详情，点击教授查看主页。",-1)),a[3]||(a[3]=e("h2",{id:"一张方向树",tabindex:"-1"},[i("一张方向树 "),e("a",{class:"header-anchor",href:"#一张方向树","aria-label":'Permalink to "一张方向树"'},"​")],-1)),a[4]||(a[4]=e("p",null,"下面按主要研究对象分成四簇，共 11 个方向。这是导航，不是学科边界：一个课题可能同时涉及器件、电路、算法与软件，图中的关联也不代表正式合作或招生关系。",-1)),(h(),l(d,null,{default:o(()=>[t(s,{id:"mermaid-14",class:"mermaid",graph:"mindmap%0A%20%20root((%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AF%E7%A0%94%E7%A9%B6%E6%96%B9%E5%90%91%E6%A0%91))%0A%20%20%20%20%E5%99%A8%E4%BB%B6%E4%B8%8E%E5%B7%A5%E8%89%BA%0A%20%20%20%20%20%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E4%B8%8E%E6%96%B0%E5%9E%8B%E5%AD%98%E5%82%A8%0A%20%20%20%20%20%20%E5%85%89%E7%94%B5%E5%AD%90%E4%B8%8E%E9%9B%86%E6%88%90%E5%85%89%E5%AD%90%0A%20%20%20%20%20%20MEMS%E3%80%81%E4%BC%A0%E6%84%9F%E4%B8%8E%E6%9F%94%E6%80%A7%E7%94%B5%E5%AD%90%0A%20%20%20%20%E7%94%B5%E8%B7%AF%E8%AE%BE%E8%AE%A1%0A%20%20%20%20%20%20%E6%95%B0%E5%AD%97%20VLSI%20%E4%B8%8E%E4%B8%93%E7%94%A8%E8%8A%AF%E7%89%87%0A%20%20%20%20%20%20%E6%A8%A1%E6%8B%9F%E4%B8%8E%E6%B7%B7%E5%90%88%E4%BF%A1%E5%8F%B7%0A%20%20%20%20%20%20%E7%94%B5%E6%BA%90%E7%AE%A1%E7%90%86%E4%B8%8E%E5%8A%9F%E7%8E%87%E7%94%B5%E5%AD%90%0A%20%20%20%20%20%20%E5%B0%84%E9%A2%91%E3%80%81%E5%BE%AE%E6%B3%A2%E4%B8%8E%E7%94%B5%E7%A3%81%0A%20%20%20%20%E7%B3%BB%E7%BB%9F%E4%B8%8E%E6%9E%B6%E6%9E%84%0A%20%20%20%20%20%20AI%20%E8%8A%AF%E7%89%87%E4%B8%8E%E6%96%B0%E5%9E%8B%E8%AE%A1%E7%AE%97%0A%20%20%20%20%20%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84%E4%B8%8E%E7%B3%BB%E7%BB%9F%0A%20%20%20%20%20%20%E7%A1%AC%E4%BB%B6%E5%AE%89%E5%85%A8%E4%B8%8E%E9%9A%90%E7%A7%81%E8%AE%A1%E7%AE%97%0A%20%20%20%20%E8%AE%BE%E8%AE%A1%E6%96%B9%E6%B3%95%E5%AD%A6%0A%20%20%20%20%20%20EDA%20%E4%B8%8E%E5%8F%AF%E5%88%B6%E9%80%A0%E6%80%A7%E8%AE%BE%E8%AE%A1%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<h2 id="方向巡礼" tabindex="-1">方向巡礼 <a class="header-anchor" href="#方向巡礼" aria-label="Permalink to &quot;方向巡礼&quot;">​</a></h2><h3 id="半导体器件与新型存储" tabindex="-1">半导体器件与新型存储 <a class="header-anchor" href="#半导体器件与新型存储" aria-label="Permalink to &quot;半导体器件与新型存储&quot;">​</a></h3><p>研究晶体管、存储单元与新材料结构如何产生可用的电学行为，关注的不只是尺寸，还有可靠性、能耗和制造条件。上科大相关公开方向包括自旋电子、磁存储、宽禁带器件与低温电子学。喜欢从物理机制解释实验曲线，可以从这里出发，再追问器件怎样进入电路。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/devices">器件与新型存储</a></p><h3 id="光电子与集成光子" tabindex="-1">光电子与集成光子 <a class="header-anchor" href="#光电子与集成光子" aria-label="Permalink to &quot;光电子与集成光子&quot;">​</a></h3><p>把产生、传输、调制和探测光的功能做进芯片，连接通信、感知与计算。上科大相关研究覆盖高速探测器、激光器、光互联、非线性与量子光芯片以及光计算。它既需要电磁场与器件基础，也常常需要控制电路、封装和系统测量。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/photonics">光电子与集成光子</a></p><h3 id="mems、传感与柔性电子" tabindex="-1">MEMS、传感与柔性电子 <a class="header-anchor" href="#mems、传感与柔性电子" aria-label="Permalink to &quot;MEMS、传感与柔性电子&quot;">​</a></h3><p>微机电系统（MEMS）让微小结构的运动、振动或形变成为可读出的信号。上科大的相关方向包括压电微系统、柔性电子、多层级微纳传感与精密电磁传感。这里常见的挑战是机械、电学、材料和封装相互影响，不能只看单一器件指标。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/mems-sensors">MEMS、传感与柔性电子</a></p><h3 id="数字-vlsi-与专用芯片" tabindex="-1">数字 VLSI 与专用芯片 <a class="header-anchor" href="#数字-vlsi-与专用芯片" aria-label="Permalink to &quot;数字 VLSI 与专用芯片&quot;">​</a></h3><p>超大规模集成电路（VLSI）设计把算法变成满足时序、功耗与面积约束的数字硬件。上科大的相关方向包含 FPGA、低功耗电路、先进计算与视觉专用芯片；<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/vsplab">VSPLab</a> 的三维重建与渲染芯片是值得关注的入口。会写硬件描述语言只是起点，验证、存储组织和物理实现同样重要。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi">数字 VLSI 与专用芯片</a></p><h3 id="模拟与混合信号" tabindex="-1">模拟与混合信号 <a class="header-anchor" href="#模拟与混合信号" aria-label="Permalink to &quot;模拟与混合信号&quot;">​</a></h3><p>模拟电路处理真实世界的连续信号，混合信号电路连接模拟域与数字域。上科大的公开研究中，医疗电子、脑机接口与植入式芯片是鲜明的应用入口。噪声、失真、功耗和安全边界必须一起考虑，而不是把理想公式直接搬到版图。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/analog-mixed">模拟与混合信号</a></p><h3 id="电源管理与功率电子" tabindex="-1">电源管理与功率电子 <a class="header-anchor" href="#电源管理与功率电子" aria-label="Permalink to &quot;电源管理与功率电子&quot;">​</a></h3><p>这一方向研究如何高效、稳定地转换和分配能量，从芯片电源到系统级变换器都有问题。上科大相关研究包括电源管理芯片、算力电源、无线传能、能量收集与宽禁带器件应用。喜欢电路又关心控制、磁性元件和实际负载，可以沿这条线探索。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/power">电源管理与功率电子</a></p><h3 id="射频、微波与电磁" tabindex="-1">射频、微波与电磁 <a class="header-anchor" href="#射频、微波与电磁" aria-label="Permalink to &quot;射频、微波与电磁&quot;">​</a></h3><p>频率升高后，连线、封装和空间结构本身都会参与信号传播，必须把电路与场结合起来理解。上科大相关方向包括天线、微波与毫米波器件、超构表面、太赫兹器件和电磁成像。研究可能落在通信前端，也可能落在传感、成像或电磁设计方法。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/rf-em">射频、微波与电磁</a></p><h3 id="ai-芯片与新型计算" tabindex="-1">AI 芯片与新型计算 <a class="header-anchor" href="#ai-芯片与新型计算" aria-label="Permalink to &quot;AI 芯片与新型计算&quot;">​</a></h3><p>研究如何让智能算法在计算、访存、精度和能耗约束下高效运行。上科大的相关路线既有数字计算电路与边缘 AI，也有自旋类脑计算和光计算，不能把它们视作同一种技术。<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee219">EE219 智能计算系统</a> 可作为连接算法与硬件的课程入口。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/ai-hardware">AI 芯片与新型计算</a></p><h3 id="计算机体系结构与系统" tabindex="-1">计算机体系结构与系统 <a class="header-anchor" href="#计算机体系结构与系统" aria-label="Permalink to &quot;计算机体系结构与系统&quot;">​</a></h3><p>关注指令、流水线、缓存、并行执行和系统软件如何协同支撑真实程序。上科大相关研究横跨先进计算电路、操作系统、存储系统、高性能计算与微架构安全。可以从 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cs110">CS110</a> 建立整体图景，再借 RISC-V 与开源 GPGPU 找到可复现的研究对象。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/architecture">计算机体系结构与系统</a></p><h3 id="硬件安全与隐私计算" tabindex="-1">硬件安全与隐私计算 <a class="header-anchor" href="#硬件安全与隐私计算" aria-label="Permalink to &quot;硬件安全与隐私计算&quot;">​</a></h3><p>研究计算平台怎样在攻击者存在时仍然守住机密性、完整性和隔离边界。上科大的相关公开方向包含侧信道、可信执行环境、硬件安全与隐私计算芯片。一个设计是否安全取决于威胁模型和证据，而不只是使用了某种加密算法。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/hardware-security">硬件安全与隐私计算</a></p><h3 id="eda-与可制造性设计" tabindex="-1">EDA 与可制造性设计 <a class="header-anchor" href="#eda-与可制造性设计" aria-label="Permalink to &quot;EDA 与可制造性设计&quot;">​</a></h3><p>电子设计自动化（EDA）把逻辑、电路和版图问题转化为算法、优化与工程工具。上科大相关方向包括 AI4EDA、设计空间探索、物理设计、可制造性设计和计算光刻。适合既喜欢算法、数学，又愿意理解真实芯片约束的同学；EE215A 与 SI365 是相关课程入口。→ <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/eda">EDA 与可制造性设计</a></p><h2 id="如何选方向" tabindex="-1">如何选方向 <a class="header-anchor" href="#如何选方向" aria-label="Permalink to &quot;如何选方向&quot;">​</a></h2><p><strong>自底向上：从课程中找兴趣。</strong> 留意自己更愿意追问哪类问题：为什么器件曲线如此变化，为什么电路会振荡，为什么程序访存受限，还是为什么一个优化器难以收敛？课程成绩不是兴趣的唯一证据；能否持续阅读、动手和解释失败更有参考价值。</p><p><strong>自顶向下：从产业或科研问题反推。</strong> 例如“让边缘视觉系统更省电”可能牵涉传感、低比特计算、存储层级和电源管理。先划清问题、评价指标和实验资源，再决定自己的切入层级，不必一开始就锁定某个热门标签。</p><p><strong>与 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/">学习地图</a> 配合。</strong> 方向页用于认识问题和团队，学习地图用于安排基础与实践。可以先选一个相邻方向做小型阅读或复现实验，把“对标签感兴趣”变成“对具体问题有判断”；联系课题组前查阅近期论文和最新主页，招生信息以学院及老师公布为准。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你在相关课题组做过科研，欢迎通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充公开的研究问题、入门路径与进组准备建议，不提交个人隐私或未公开成果。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上海科技大学信息科学与技术学院</a>：教授卡片链接对应公开个人主页。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔器件与集成系统中心介绍材料</a>：约 2024 年材料，仅用于方向介绍，不作为当前招生或人员状态证明。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：实际开课以教务系统为准。</li><li><a href="https://vsplab.cn/" target="_blank" rel="noreferrer">VSPLab</a>：数字视觉与图形芯片研究入口。</li></ul>',30))])}const q=c(B,[["render",p]]);export{x as __pageData,q as default};
